#!/bin/bash
# The generation track's shared harness (docs/reports/GEN_TRACK.md, GEN-A).
#
#   scripts/gen_eval.sh dev|test LABEL OUTDIR [cyphalm_trie sample flags...]
#
# 1. cyphalm_trie sample on bench/eval/gen_prompts_{dev,test}.tsv (250 prompts, 3 temperatures, the fixed seeds of
#    `sample`), any flags passed through; it also prints the BPC of the human continuations under sampling's mixture
#    and the share of generated bytes in 32-byte spans of the training bytes.
# 2. scribe ladder (SCRIBE v2, the control ladder of PLAN 6.4) on the GEN lines.
# 3. A summary: SCRIBE and surface S with 95% intervals (pooled and per temperature), continuation BPC, copy shares,
#    SCRIBE's integrity distance D_I, mean length, and five samples. OUTDIR/LABEL.summary.md.
#
# The test split is read once per change; log the read in GEN_TRACK.md's Reads table.
#
# Environment (defaults in brackets):
#   CYPHALM_TRIE  the cyphalm_trie binary [native/build/cyphalm_trie]
#   SCRIBE        the scribe binary [native/build/scribe]
#   WIKI          the corpus `sample` trains on (its first --train bytes) [/root/cdata/enwik8]
#   ENWIK8        enwik8, for SCRIBE's pack, reference and human rungs [/root/cdata/enwik8]
#   SCRIBE_VEC    SCRIBE's word vectors (docs/reports/SCRIBE_V2.md) [/root/work/scribe/vec32]
#
# Author: Odin Loch
set -euo pipefail
if [ $# -lt 3 ]; then
    echo "usage: scripts/gen_eval.sh dev|test LABEL OUTDIR [cyphalm_trie sample flags...]" >&2
    exit 2
fi
SPLIT=$1; LABEL=$2; OUT=$3; shift 3
case "$SPLIT" in dev|test) ;; *) echo "split must be dev or test" >&2; exit 2;; esac
ROOT=$(cd "$(dirname "$0")/.." && pwd)
TRIE=${CYPHALM_TRIE:-$ROOT/native/build/cyphalm_trie}
SC=${SCRIBE:-$ROOT/native/build/scribe}
WIKI=${WIKI:-/root/cdata/enwik8}
E=${ENWIK8:-/root/cdata/enwik8}
VEC=${SCRIBE_VEC:-/root/work/scribe/vec32}
PROMPTS=$ROOT/bench/eval/gen_prompts_$SPLIT.tsv
mkdir -p "$OUT"
G=$OUT/$LABEL.gen.txt
if [ "$SPLIT" = test ]; then echo "gen_eval: TEST read ($LABEL); log it in docs/reports/GEN_TRACK.md" >&2; fi
nice -n 5 "$TRIE" sample "$WIKI" "$G" --prompts-file "$PROMPTS" "$@" > "$OUT/$LABEL.sample.out" 2> "$OUT/$LABEL.sample.err"
nice -n 5 "$SC" ladder --pack "enwik:$E:16:48" --ref "enwik:$E:48:56" --test "enwik:$E:56:64" --vectors "$VEC" \
    --profile v2 --seed 20261027 --gen-trie "$G" --label "$LABEL" > "$OUT/$LABEL.scribe.md" 2> "$OUT/$LABEL.scribe.err"
python3 -I "$ROOT/scripts/gen_eval_summary.py" "$OUT" "$LABEL" "$SPLIT" | tee "$OUT/$LABEL.summary.md"
